-- PT105-S4-Q3. Batch 07.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT105-S4-Q3$batch07$ AND q.stimulus=$batch07$Nutritionist: A study revealed that although most adults estimated their diets to correspond closely with the recommendations of standard nutritional guidelines, most of their diets did not come close to those recommendations. Both women and men underestimated the amount of fat in their diets and overestimated their intake of most other foods. In most food categories, especially fruits and vegetables, women's diets did not meet the recommendations. Men underestimated their fat intake by half, and though they met the recommendations for breads, they fell short in all other categories.$batch07$ AND q.prompt=$batch07$Which one of the following is most strongly supported by the information offered by the nutritionist?$batch07$ AND q.correct_choice=$batch07$E$batch07$) THEN RAISE EXCEPTION 'Question changed: PT105-S4-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT105-S4-Q3$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT105-S4-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT105-S4-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Statements$batch07$, $batch07$Most adults in the study thought their diets matched the guidelines, but most didn't. Everyone underestimated fat and overestimated most other foods. Women missed the targets in most categories, especially fruits and vegetables. Men underestimated fat by half, met the target for breads, and fell short in every other category.$batch07$), (1, $batch07$Evaluate$batch07$, $batch07$Pause and infer on the men. "Fell short in all other categories" means every category except breads. Fruits and vegetables are a category, so men in the study fell short on fruits and vegetables. That is a direct consequence of the last sentence.$batch07$), (2, $batch07$Goal$batch07$, $batch07$Men in the study didn't eat the recommended fruits and vegetables.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT105-S4-Q3$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$This is the most popular wrong answer. "Every food category" is the problem. We know people overestimated "most other foods", not all of them, and men actually met the bread target. We have no evidence that anyone misjudged breads. One category is enough to sink "every".$batch07$), ($batch07$B$batch07$, $batch07$The passage says nothing about how many men or women were *aware* of falling short.$batch07$), ($batch07$C$batch07$, $batch07$Men met the bread target, but that doesn't mean they were more aware of it, and the passage never says what women knew about breads.$batch07$), ($batch07$D$batch07$, $batch07$People overestimated their intake of most foods other than fat. If anything, men thought they ate *more* fruits and vegetables than they did, not less.$batch07$), ($batch07$E$batch07$, $batch07$Men "fell short in all other categories" besides breads, which includes fruits and vegetables. The passage describes the men as a group, so "most men" is a safe reading.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT105-S4-Q3$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
